#!/usr/bin/env python3
from __future__ import annotations
import argparse, csv, json, re
from pathlib import Path

CHAPTERS = [('I/01', 'Scalars, Vectors and Linear Combinations', 'ch01_scalars_vectors_and_linear_combinations'), ('I/02', 'Subspaces, Span and Linear Independence', 'ch02_subspaces_span_and_linear_independence'), ('I/03', 'Bases and Dimension', 'ch03_bases_and_dimension'), ('I/04', 'Coordinates and Change of Basis', 'ch04_coordinates_and_change_of_basis'), ('I/05', 'Linear Transformations', 'ch05_linear_transformations'), ('I/06', 'Kernels, Images and Isomorphisms', 'ch06_kernels_images_and_isomorphisms'), ('I/07', 'Matrix Representation of Linear Maps', 'ch07_matrix_representation_of_linear_maps'), ('I/08', 'Determinants and Trace', 'ch08_determinants_and_trace'), ('I/09', 'Eigenvalues and Eigenvectors', 'ch09_eigenvalues_and_eigenvectors'), ('I/10', 'Invariant Subspaces and Triangularization', 'ch10_invariant_subspaces_and_triangularization'), ('I/11', 'Diagonalization and Minimal Polynomials', 'ch11_diagonalization_and_minimal_polynomials'), ('I/12', 'Canonical Forms', 'ch12_canonical_forms'), ('I/13', 'Inner Products and Orthogonality', 'ch13_inner_products_and_orthogonality'), ('I/14', 'Gram–Schmidt and Orthogonal Projection', 'ch14_gram_schmidt_and_orthogonal_projection'), ('I/15', 'Orthogonal and Unitary Operators', 'ch15_orthogonal_and_unitary_operators'), ('I/16', 'The Spectral Theorem', 'ch16_the_spectral_theorem'), ('I/17', 'Quadratic Forms', 'ch17_quadratic_forms'), ('I/18', 'Singular-Value Decomposition', 'ch18_singular_value_decomposition')]
DATA = {'I/01': {'intro': 'Linear algebra begins with two operations: adding vectors and scaling them by elements of a field. The point of the abstract definition is not to hide geometry but to identify exactly which arguments depend only on those operations. This chapter moves back and forth between concrete coordinate vectors, functions and polynomials so that linear combinations become a working language rather than a formal slogan.', 'sections': [('Fields and scalars', 'We work over a field $\\mathbb F$, usually $\\mathbb R$ or $\\mathbb C$. The field laws allow addition, subtraction, multiplication and division by nonzero scalars. Every vector-space identity ultimately rests on these laws together with the vector-space axioms.'), ('Vector spaces', 'A vector space $V$ over $\\mathbb F$ is an abelian group under addition equipped with scalar multiplication $\\mathbb F\\times V\\to V$ satisfying distributivity, compatibility, and $1v=v$. The zero vector is unique, and $0v=0$, $a0=0$, and $(-1)v=-v$ follow from the axioms.'), ('Linear combinations', 'Given $v_1,\\ldots,v_r\\in V$, a linear combination is $a_1v_1+\\cdots+a_rv_r$ with $a_i\\in\\mathbb F$. Finite linear combinations are the algebraic mechanism for building new vectors from old ones.'), ('Concrete models', 'The spaces $\\mathbb F^n$, polynomial spaces $\\mathbb F[x]$, matrix spaces $M_{m,n}(\\mathbb F)$, and function spaces $\\mathbb F^X$ all satisfy the same vector-space axioms. Coordinatewise formulas are examples of a common structure.'), ('Affine versus linear geometry', 'Linear combinations with arbitrary coefficients preserve the origin. Affine combinations impose $a_1+\\cdots+a_r=1$ and describe points in affine hulls. Convex combinations add $a_i\\ge0$ and describe convex hulls.'), ('Complex scalars and realification', 'A complex vector space is automatically a real vector space after restricting scalars, but its real dimension doubles when the complex dimension is finite. Forgetting part of the scalar field changes the linear relations that are allowed.')], 'facts': [('Uniqueness consequences of the axioms', 'For every vector space $V$, the zero vector and additive inverse of each vector are unique; moreover $0v=0$, $a0=0$, and $(-a)v=-(av)$ for all $a\\in\\mathbb F$.', 'Each identity follows by adding a suitable additive inverse and using distributivity. For example, $0v=(0+0)v=0v+0v$; cancelling $0v$ gives $0v=0$.'), ('Linear-combination regrouping', 'A linear combination of linear combinations is again a linear combination of the original vectors.', 'Substitute each inner expression and use associativity and distributivity to collect the coefficient of each original vector.')], 'examples': [('Polynomials', 'In $\\mathbb R[x]$, the polynomial $3-2x+5x^3$ is a linear combination of $1,x,x^3$. The same expression may be viewed inside any larger polynomial space without changing its coefficients.'), ('Functions', 'If $f,g:X\\to\\mathbb R$, then $2f-3g$ is the function $x\\mapsto 2f(x)-3g(x)$. Function spaces make clear that vectors need not be arrows.'), ('Matrices', 'The matrix $\\begin{pmatrix}1&2\\\\0&-1\\end{pmatrix}$ is a linear combination of the four matrix units $E_{ij}$. Matrix units play the role of coordinate directions.')], 'ex': [('Show directly from the axioms that $a(-v)=-(av)$.', 'Use $v+(-v)=0$, multiply by $a$, and use distributivity. The resulting equation $av+a(-v)=0$ says that $a(-v)$ is the additive inverse of $av$.'), ('Write $(2,-1,3)$ as a linear combination of the standard vectors of $\\mathbb R^3$.', '$(2,-1,3)=2e_1-e_2+3e_3$.'), ('Give a vector-space structure on the set of real-valued continuous functions on $[0,1]$.', 'Use pointwise addition and scalar multiplication. Continuity is preserved by both operations, so the operations remain inside the set.'), ('Why is the unit circle in $\\mathbb R^2$ not a vector space?', 'It does not contain the zero vector and is not closed under scalar multiplication; for example $2(1,0)=(2,0)$ is not on the unit circle.'), ('Over which scalars is $\\mathbb C$ naturally a one-dimensional vector space? What is its dimension over $\\mathbb R$?', 'It is one-dimensional over $\\mathbb C$, with basis $\\{1\\}$, and two-dimensional over $\\mathbb R$, with basis $\\{1,i\\}$.'), ('Find an affine combination of $(0,0)$ and $(2,0)$ giving $(3,0)$.', 'Take coefficients $-\\tfrac12$ and $\\tfrac32$; they sum to $1$ and give $(3,0)$.'), ('Show that the set of all $2\\times2$ real matrices is a vector space.', 'Matrix addition is an abelian group operation and scalar multiplication satisfies the vector-space laws entrywise.'), ('Explain why a finite sum $\\sum_i a_i v_i$ is independent of parentheses.', 'Associativity of vector addition allows any parenthesization; a formal induction on the number of summands proves the claim.')]}, 'I/02': {'intro': 'Subspaces are the linear subsets of a vector space, span is the smallest subspace generated by specified vectors, and linear independence is the condition that a generating description has no redundancy. These three ideas form the basic grammar of finite-dimensional reasoning.', 'sections': [('Subspaces', 'A subset $W\\subseteq V$ is a subspace when it contains $0$ and is closed under addition and scalar multiplication. Equivalently, $au+bv\\in W$ for all $u,v\\in W$ and $a,b\\in\\mathbb F$.'), ('Intersections and sums', 'Arbitrary intersections of subspaces are subspaces. The union of two subspaces need not be a subspace, but the sum $U+W=\\{u+w\\}$ always is.'), ('Span', 'The span of $S\\subseteq V$ is the set of all finite linear combinations of elements of $S$. It is the smallest subspace containing $S$.'), ('Linear dependence', 'A finite list $v_1,\\ldots,v_r$ is linearly dependent when some nontrivial scalar relation $a_1v_1+\\cdots+a_rv_r=0$ exists. Otherwise the list is linearly independent.'), ('Redundancy and exchange', 'If a list is dependent, at least one vector is in the span of the others. This simple observation drives the exchange arguments used to prove uniqueness of dimension.'), ('Homogeneous systems', 'Columns of a matrix are linearly dependent exactly when the corresponding homogeneous system has a nonzero solution. Row reduction converts an abstract dependence question into an algorithm.')], 'facts': [('Subspace criterion', 'A nonempty subset $W\\subseteq V$ is a subspace if and only if $au+bv\\in W$ for all $u,v\\in W$ and all scalars $a,b$.', 'Taking $a=b=0$ gives $0\\in W$; special choices recover closure under addition and scalar multiplication. The converse is immediate.'), ('Dependence lemma', 'A list $v_1,\\dots,v_r$ is dependent if and only if one vector lies in the span of the preceding vectors after a suitable reordering.', 'Solve a nontrivial relation for a vector whose coefficient is nonzero. Conversely, any span relation rearranges to a nontrivial dependence relation.')], 'examples': [('Solution spaces', 'The solution set of a homogeneous linear system $Ax=0$ is a subspace of $\\mathbb F^n$ because matrix multiplication is linear.'), ('Polynomial constraints', 'Polynomials of degree at most $4$ satisfying $p(1)=0$ form a subspace: evaluation at $1$ respects addition and scalar multiplication.'), ('A nonexample', 'The set $\\{(x,y):xy=0\\}$ is the union of the coordinate axes and is not a subspace because $(1,0)+(0,1)=(1,1)$ leaves the set.')], 'ex': [('Show that the intersection of any family of subspaces is a subspace.', 'The zero vector lies in every member. If two vectors lie in the intersection, every linear combination lies in each member and hence in the intersection.'), ('Show that $U\\cup W$ is a subspace only if $U\\subseteq W$ or $W\\subseteq U$.', 'If neither contains the other, choose $u\\in U\\setminus W$ and $w\\in W\\setminus U$. Then $u+w$ belongs to neither subspace, contradicting closure.'), ('Find the span of $(1,0,1)$ and $(0,1,1)$ in $\\mathbb R^3$.', 'It is $\\{(a,b,a+b):a,b\\in\\mathbb R\\}$, equivalently the plane $z=x+y$.'), ('Are $1+x$, $x+x^2$, and $1-x^2$ independent?', 'No. The first minus the second minus the third is zero: $(1+x)-(x+x^2)-(1-x^2)=0$.'), ('Prove that a list containing the zero vector is dependent.', 'Give the zero vector coefficient $1$ and all other vectors coefficient $0$.'), ('Determine whether $(1,2)$ and $(2,4)$ are independent.', 'They are dependent because $(2,4)=2(1,2)$.'), ('Show that the span of a set equals the intersection of all subspaces containing it.', 'The span is itself a subspace containing the set, and every subspace containing the set contains all its finite linear combinations.'), ('Relate pivots in a matrix to independence of its columns.', 'A homogeneous system $Ax=0$ has only the zero solution exactly when every column variable is a pivot variable; this is equivalent to column independence.')]}, 'I/03': {'intro': 'A basis is simultaneously a generating system and a coordinate system with no redundancy. Finite-dimensional vector spaces become computationally manageable because every vector then has a unique finite coordinate list. Dimension records the size of any basis and is independent of the particular basis chosen.', 'sections': [('Bases', 'A basis of $V$ is a linearly independent list that spans $V$. The two conditions guarantee existence and uniqueness of coordinates.'), ('Coordinates relative to a basis', 'If $B=(v_1,\\ldots,v_n)$ is a basis, every $v$ has a unique representation $v=\\sum a_i v_i$. The coordinate column is written $[v]_B$.'), ('Extension and reduction', 'An independent list in a finite-dimensional space can be extended to a basis, while a spanning list can be reduced to a basis by deleting redundant vectors.'), ('Dimension', 'All bases of a finite-dimensional vector space have the same number of vectors. That common number is $\\dim V$.'), ('Dimension of subspaces', 'If $W\\subseteq V$ and $V$ is finite-dimensional, then $\\dim W\\le\\dim V$, with equality only when $W=V$.'), ('Dimension formula', 'For finite-dimensional subspaces $U,W\\subseteq V$, $\\dim(U+W)=\\dim U+\\dim W-\\dim(U\\cap W)$.')], 'facts': [('Basis uniqueness of coordinates', 'A list is a basis if and only if every vector has a unique representation as a linear combination of the list.', 'Spanning gives existence. If two representations exist, subtract them to obtain a dependence relation; independence forces equal coefficients.'), ('Dimension formula for sums', 'For finite-dimensional $U,W$, one has $\\dim(U+W)=\\dim U+\\dim W-\\dim(U\\cap W)$.', 'Choose a basis of $U\\cap W$, extend it separately to bases of $U$ and $W$, and check that the union of the extensions spans $U+W$ and is independent.')], 'examples': [('Polynomial dimension', 'The space $\\mathcal P_n$ of polynomials of degree at most $n$ has basis $1,x,\\ldots,x^n$ and dimension $n+1$.'), ('Symmetric matrices', 'The real symmetric $n\\times n$ matrices have dimension $n(n+1)/2$, one free entry for each diagonal or upper-triangular position.'), ('Trace-zero matrices', 'The trace-zero subspace of $M_n(\\mathbb F)$ has dimension $n^2-1$.')], 'ex': [('Show that $(1,0),(1,1)$ is a basis of $\\mathbb R^2$.', 'The two vectors are not scalar multiples, so they are independent; two independent vectors in a two-dimensional space form a basis.'), ('Find the coordinates of $(3,2)$ in the basis $((1,0),(1,1))$.', 'Solve $a(1,0)+b(1,1)=(3,2)$. Then $b=2$ and $a=1$, so the coordinate column is $(1,2)^T$.'), ('Find a basis for polynomials in $\\mathcal P_3$ satisfying $p(0)=0$.', 'The condition kills the constant term, so $x,x^2,x^3$ is a basis.'), ('Why can no four vectors in $\\mathbb R^3$ be independent?', 'Any independent list has length at most the dimension, which is $3$.'), ('If $U\\subseteq V$ and $\\dim U=\\dim V<\\infty$, prove $U=V$.', 'A basis of $U$ is an independent list in $V$ of full dimension, hence already a basis of $V$.'), ('Compute the dimension of skew-symmetric $n\\times n$ matrices over a field of characteristic not $2$.', 'Diagonal entries are zero and entries below the diagonal are determined by those above it, giving $n(n-1)/2$.'), ('Suppose $\\dim U=3$, $\\dim W=4$, and $\\dim(U\\cap W)=2$. Find $\\dim(U+W)$.', 'The dimension formula gives $3+4-2=5$.'), ('Explain why every finite spanning set contains a basis.', 'Repeatedly delete any vector lying in the span of the others. The process terminates and preserves span; the remaining list is independent.')]}, 'I/04': {'intro': 'Coordinates turn an abstract vector space into a copy of $\\mathbb F^n$, but the copy depends on a chosen basis. Change-of-basis matrices explain precisely how two coordinate descriptions of the same vector are related. This is the first systematic appearance of conjugation and covariance.', 'sections': [('Coordinate isomorphisms', 'For an ordered basis $B=(v_1,\\ldots,v_n)$, the coordinate map $\\kappa_B:V\\to\\mathbb F^n$, $v\\mapsto[v]_B$, is a linear isomorphism.'), ('Transition matrices', 'Given bases $B,C$, the matrix $P_{C\\leftarrow B}$ is defined by $[v]_C=P_{C\\leftarrow B}[v]_B$. Its columns are the $C$-coordinates of the vectors of $B$.'), ('Inverse transitions', 'Changing from $B$ to $C$ and back gives $P_{B\\leftarrow C}=P_{C\\leftarrow B}^{-1}$.'), ('Coordinate covariants', 'Vectors and linear maps do not change when the basis changes; their coordinate arrays do. Good notation separates the object from its representation.'), ('Dual coordinates', 'Linear functionals transform by the inverse transpose of the vector change-of-basis matrix. This anticipates the distinction between vectors and covectors.'), ('Conditioning of bases', 'A mathematically valid basis can be numerically poor if its vectors are nearly dependent. Orthogonal bases mitigate this instability.')], 'facts': [('Transition matrix rule', 'The columns of $P_{C\\leftarrow B}$ are $[v_1]_C,\\ldots,[v_n]_C$ when $B=(v_1,\\ldots,v_n)$.', 'Apply the transition identity to each basis vector. Its $B$-coordinate is the corresponding standard vector, so the resulting $C$-coordinate is the corresponding column.'), ('Cocycle identity', 'For bases $B,C,D$, $P_{D\\leftarrow B}=P_{D\\leftarrow C}P_{C\\leftarrow B}$.', 'Apply the two coordinate changes successively to an arbitrary coordinate vector and use uniqueness of the representing matrix.')], 'examples': [('Two planar bases', 'For $B=((1,0),(1,1))$ and standard $E$, $P_{E\\leftarrow B}=\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}$.'), ('Polynomial bases', 'The monomial basis and shifted basis $1,(x-1),(x-1)^2$ of $\\mathcal P_2$ are related by expanding powers of $x-1$.'), ('Scaling a basis', 'Replacing $v_i$ by $c_i v_i$ multiplies the corresponding transition column by $c_i$.')], 'ex': [('Compute $P_{E\\leftarrow B}$ for $B=((1,1),(1,-1))$.', 'Its columns are the basis vectors in standard coordinates: $\\begin{pmatrix}1&1\\\\1&-1\\end{pmatrix}$.'), ('Find $P_{B\\leftarrow E}$ for the preceding basis.', 'Invert the matrix to get $\\frac12\\begin{pmatrix}1&1\\\\1&-1\\end{pmatrix}$.'), ('Verify the cocycle identity for three arbitrary bases.', 'For every $v$, substitute $[v]_C=P_{C\\leftarrow B}[v]_B$ into $[v]_D=P_{D\\leftarrow C}[v]_C$; equality for all coordinate vectors gives the matrix identity.'), ('Why must every transition matrix be invertible?', 'It represents the composition of two coordinate isomorphisms, hence an isomorphism.'), ('Compute coordinates of $p(x)=x^2$ in $B=(1,x-1,(x-1)^2)$.', 'Since $x=(x-1)+1$, $x^2=(x-1)^2+2(x-1)+1$, so the coordinates are $(1,2,1)^T$.'), ('How do coordinates change if the basis order is permuted?', 'The coordinate column is permuted inversely to the basis order; the transition is represented by a permutation matrix.'), ('Explain why the vector itself is basis-independent.', 'A basis selects a coordinate isomorphism but does not alter the element $v\\in V$; only its numerical representative changes.'), ('Why are nearly parallel planar basis vectors numerically problematic?', 'The transition matrix is close to singular, so its inverse can have large entries and amplify small data errors.')]}, 'I/05': {'intro': 'Linear transformations are the morphisms of vector spaces: they preserve exactly the operations that define linear structure. Once linearity is recognized, a map is determined by its action on a basis, compositions remain linear, and apparently different formulas become instances of the same operator calculus.', 'sections': [('Definition and first consequences', 'A map $T:V\\to W$ is linear if $T(av+bw)=aT(v)+bT(w)$. Then $T(0)=0$ and all finite linear combinations pass through $T$.'), ('Determination by a basis', 'A linear map is uniquely determined by its values on a basis of the domain. Conversely, arbitrary images of basis vectors extend uniquely to a linear map.'), ('Algebra of operators', 'For fixed $V,W$, the set $\\mathcal L(V,W)$ is a vector space under pointwise addition and scalar multiplication. Endomorphisms $\\mathcal L(V)$ also compose.'), ('Composition', 'The composite of linear maps is linear. Composition is associative and distributes over addition but is generally not commutative.'), ('Inverse maps', 'A bijective linear map has a linear inverse. Such maps are isomorphisms and identify vector spaces as having the same linear structure.'), ('Important operators', 'Differentiation on polynomials, evaluation functionals, coordinate projections, inclusion maps, shifts, and matrix multiplication are canonical examples.')], 'facts': [('Extension from a basis', 'If $B=(v_1,\\ldots,v_n)$ is a basis of $V$ and $w_i\\in W$ are arbitrary, there is a unique linear $T:V\\to W$ with $T(v_i)=w_i$.', 'Write each $v$ uniquely as $\\sum a_i v_i$ and define $T(v)=\\sum a_iw_i$. Uniqueness follows because any linear map must use this formula.'), ('Inverse of an isomorphism', 'If $T:V\\to W$ is linear and bijective, then $T^{-1}:W\\to V$ is linear.', 'Write $y_j=T(x_j)$. Then $T^{-1}(ay_1+by_2)=T^{-1}(T(ax_1+bx_2))=ax_1+bx_2$.')], 'examples': [('Differentiation', "$D:\\mathcal P_n\\to\\mathcal P_{n-1}$, $D(p)=p'$, is linear because differentiation respects sums and scalar multiples."), ('Evaluation', 'For fixed $a$, $E_a(p)=p(a)$ is a linear functional on a polynomial space.'), ('Shear', '$T(x,y)=(x+y,y)$ is linear and invertible, with inverse $(u,v)\\mapsto(u-v,v)$.')], 'ex': [('Show that $T(x,y)=(x+2y,3x-y)$ is linear.', 'Each output coordinate is a homogeneous linear expression in $x,y$, so direct substitution verifies preservation of linear combinations.'), ('Is $T(x,y)=(x+1,y)$ linear?', 'No. A linear map must send $0$ to $0$, but this map sends $(0,0)$ to $(1,0)$.'), ('Construct the unique linear map with $T(e_1)=(1,1)$ and $T(e_2)=(2,0)$.', 'For $(x,y)=xe_1+ye_2$, $T(x,y)=x(1,1)+y(2,0)=(x+2y,x)$.'), ('Show that composition of linear maps is linear.', 'Apply the inner map to a linear combination, then use linearity of the outer map.'), ('Prove that two linear maps agreeing on a basis agree everywhere.', 'Every vector is a linear combination of basis vectors, and both maps distribute over that combination.'), ('Give a nonzero nilpotent operator on $\\mathbb R^2$.', 'Take $N(x,y)=(y,0)$. Then $N\\ne0$ but $N^2=0$.'), ('Show that $\\mathcal L(V,W)$ is a vector space.', 'Verify the vector-space axioms pointwise; the zero vector is the zero map.'), ('Explain why a bijective nonlinear map need not be an isomorphism of vector spaces.', 'An isomorphism must preserve addition and scalar multiplication; bijectivity alone preserves only set structure.')]}, 'I/06': {'intro': 'Kernel and image measure exactly how a linear transformation fails to be injective or surjective. The rank–nullity theorem balances those two defects and turns structural questions into dimension counts. Quotient spaces then package the first isomorphism theorem in its natural form.', 'sections': [('Kernel', '$\\ker T=\\{v:T(v)=0\\}$ is a subspace of the domain. A linear map is injective exactly when its kernel is zero.'), ('Image and rank', '$\\operatorname{im}T=\\{T(v):v\\in V\\}$ is a subspace of the codomain. Its dimension is the rank.'), ('Rank–nullity', 'For finite-dimensional $V$, $\\dim V=\\dim\\ker T+\\dim\\operatorname{im}T$.'), ('Injective versus surjective', 'For a linear endomorphism of a finite-dimensional space, injective, surjective and bijective are equivalent.'), ('Quotients', 'For a subspace $U\\subseteq V$, the quotient $V/U$ consists of cosets $v+U$. It has dimension $\\dim V-\\dim U$ in finite dimensions.'), ('First isomorphism theorem', 'The map $V/\\ker T\\to\\operatorname{im}T$, $v+\\ker T\\mapsto T(v)$, is a well-defined linear isomorphism.')], 'facts': [('Rank–nullity theorem', 'If $T:V\\to W$ and $V$ is finite-dimensional, then $\\dim V=\\dim\\ker T+\\dim\\operatorname{im}T$.', 'Choose a basis of the kernel and extend it to a basis of $V$. The images of the added basis vectors form a basis of the image.'), ('First isomorphism theorem', 'Every linear map induces an isomorphism $V/\\ker T\\cong\\operatorname{im}T$.', 'The induced map is well-defined because changing a representative by a kernel vector does not change its image; injectivity and surjectivity are immediate.')], 'examples': [('Differentiation', 'On $\\mathcal P_n$, differentiation has kernel the constants and image $\\mathcal P_{n-1}$, so nullity $1$ plus rank $n$ equals $n+1$.'), ('Projection', 'The projection $\\mathbb R^3\\to\\mathbb R^2$, $(x,y,z)\\mapsto(x,y)$, has one-dimensional kernel and rank $2$.'), ('Trace functional', '$\\operatorname{tr}:M_n\\to\\mathbb F$ is surjective; its kernel has dimension $n^2-1$.')], 'ex': [('Find the kernel of $T(x,y,z)=(x+y,y+z)$.', 'Solve $x+y=0$ and $y+z=0$: $(x,y,z)=t(-1,1,-1)$, so the kernel is one-dimensional.'), ('Find the rank of the preceding map.', 'The domain has dimension $3$ and the kernel dimension is $1$, so rank–nullity gives rank $2$.'), ('Prove that zero kernel is equivalent to injectivity.', 'If $T(v)=T(w)$ then $T(v-w)=0$. Zero kernel forces $v=w$; the converse follows by comparing $T(v)=T(0)$.'), ('Why does surjectivity imply rank equals codomain dimension?', 'The image equals the codomain, so their dimensions are equal.'), ('Show $\\dim(V/U)=\\dim V-\\dim U$ in finite dimensions.', 'Extend a basis of $U$ to a basis of $V$; the cosets of the added basis vectors form a basis of the quotient.'), ('Compute the nullity of the trace map on $M_3(\\mathbb R)$.', 'The domain has dimension $9$, the trace map has rank $1$, so nullity is $8$.'), ('For an endomorphism of an $n$-dimensional space, show injective implies surjective.', 'Injectivity gives nullity $0$, so rank–nullity gives rank $n$, which equals the codomain dimension.'), ('Explain geometrically what quotienting $\\mathbb R^3$ by the $z$-axis does.', 'Vectors differing by a vertical displacement are identified; the quotient is two-dimensional and can be identified with the $xy$-plane.')]}, 'I/07': {'intro': 'Matrices are coordinate representations of linear maps. The matrix is not the transformation itself: it depends on chosen bases in the domain and codomain. Once this distinction is kept visible, matrix multiplication, change of basis, rank and similarity all acquire transparent conceptual meanings.', 'sections': [('Matrix of a linear map', 'For bases $B$ of $V$ and $C$ of $W$, the matrix $[T]_{C\\leftarrow B}$ is defined by $[T(v)]_C=[T]_{C\\leftarrow B}[v]_B$.'), ('Column rule', 'The $j$th column of $[T]_{C\\leftarrow B}$ is $[T(v_j)]_C$.'), ('Composition and multiplication', 'Coordinates turn composition into matrix multiplication: $[S\\circ T]=[S][T]$ with compatible bases.'), ('Identity and inverses', 'The identity has the identity matrix in the same basis. An isomorphism is represented by an invertible matrix.'), ('Change of basis for operators', 'For an endomorphism, changing from basis $B$ to $C$ gives $[T]_C=P_{C\\leftarrow B}[T]_B P_{B\\leftarrow C}$. Thus representations of the same operator are similar.'), ('Rank and row reduction', 'The rank of a matrix equals the dimension of the image of its associated linear map. Row operations preserve rank.')], 'facts': [('Matrix composition rule', 'With compatible bases, $[S\\circ T]=[S][T]$.', 'Apply both sides to an arbitrary coordinate vector and use the defining representation identity twice.'), ('Similarity under basis change', 'If $A=[T]_B$ and $P=P_{C\\leftarrow B}$, then $[T]_C=PAP^{-1}$.', 'Use $[v]_C=P[v]_B$ and express the coordinate identity for $T(v)$ in the two bases.')], 'examples': [('Derivative matrix', 'On $\\mathcal P_2$ in the monomial basis, differentiation is represented by $\\begin{pmatrix}0&1&0\\\\0&0&2\\\\0&0&0\\end{pmatrix}$.'), ('Rotation', 'A planar rotation through angle $\\theta$ has standard matrix $\\begin{pmatrix}\\cos\\theta&-\\sin\\theta\\\\\\sin\\theta&\\cos\\theta\\end{pmatrix}$.'), ('Projection', 'Projection onto the first coordinate axis has matrix $\\begin{pmatrix}1&0\\\\0&0\\end{pmatrix}$.')], 'ex': [('Find the matrix of $T(x,y)=(x+2y,3x-y)$ in the standard basis.', 'The columns are $T(e_1)=(1,3)$ and $T(e_2)=(2,-1)$, so $\\begin{pmatrix}1&2\\\\3&-1\\end{pmatrix}$.'), ('Why do columns record images of basis vectors?', 'The coordinate vector of the $j$th basis vector is $e_j$, and multiplying by a matrix selects its $j$th column.'), ('Prove that the matrix of an inverse map is the inverse matrix.', 'From $T^{-1}T=I$, the composition rule gives $[T^{-1}][T]=I$.'), ('Compute the rank of $\\begin{pmatrix}1&2\\\\2&4\\end{pmatrix}$.', 'The second row and second column are scalar multiples of the first, while the matrix is nonzero, so rank is $1$.'), ('Show that similar matrices have the same rank.', 'Left and right multiplication by invertible matrices correspond to isomorphisms and do not change image dimension.'), ('Write the standard matrix of reflection across the $x$-axis.', '$\\begin{pmatrix}1&0\\\\0&-1\\end{pmatrix}$.'), ('Explain why matrix multiplication is generally noncommutative.', 'Composition of transformations is order-sensitive; for example, a projection followed by a rotation differs from the reverse order.'), ('Relate elementary row operations to invertible matrices.', 'Each elementary row operation is left multiplication by an elementary invertible matrix.')]}, 'I/08': {'intro': 'The determinant compresses invertibility, oriented volume scaling and alternating multilinearity into one scalar. Trace measures the sum of diagonal action and is the simplest similarity invariant. Together they are the first examples of basis-independent quantities extracted from a matrix representation.', 'sections': [('Alternating multilinear characterization', 'The determinant is the unique alternating multilinear function of the columns with $\\det I=1$.'), ('Permutation formula', 'For $A=(a_{ij})$, $\\det A=\\sum_{\\sigma\\in S_n}\\operatorname{sgn}(\\sigma)\\prod_i a_{i,\\sigma(i)}$.'), ('Row operations', 'Swapping rows changes sign, scaling a row scales the determinant, and adding a multiple of one row to another leaves it unchanged.'), ('Invertibility', 'A square matrix is invertible exactly when its determinant is nonzero.'), ('Geometric meaning', 'Over $\\mathbb R$, $|\\det A|$ is the factor by which the associated linear map scales $n$-dimensional volume; the sign records orientation.'), ('Trace', '$\\operatorname{tr}(A)=\\sum_i a_{ii}$ is linear and satisfies $\\operatorname{tr}(AB)=\\operatorname{tr}(BA)$, hence is invariant under similarity.')], 'facts': [('Multiplicativity of determinant', 'For square matrices $A,B$, $\\det(AB)=\\det(A)\\det(B)$.', 'For fixed $B$, the map sending the columns of $A$ to $\\det(AB)$ is alternating multilinear and has normalization $\\det(B)$ at $A=I$; uniqueness gives the formula.'), ('Cyclic trace identity', 'For compatible square matrices, $\\operatorname{tr}(AB)=\\operatorname{tr}(BA)$.', 'Expand the diagonal entries: $\\operatorname{tr}(AB)=\\sum_{i,j}a_{ij}b_{ji}$ and interchange the dummy indices.')], 'examples': [('Triangular matrices', 'The determinant of a triangular matrix is the product of its diagonal entries, and its trace is their sum.'), ('Area scaling', 'The matrix $\\begin{pmatrix}2&1\\\\0&3\\end{pmatrix}$ scales signed area by $6$.'), ('Shear', 'A shear $\\begin{pmatrix}1&t\\\\0&1\\end{pmatrix}$ has determinant $1$ although it changes angles.')], 'ex': [('Compute $\\det\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}$.', 'The permutation formula gives $ad-bc$.'), ('Show that a matrix with two equal columns has determinant zero.', 'Alternation changes the determinant sign when the equal columns are swapped, but the matrix is unchanged, so the determinant equals its negative.'), ('Why is $\\det A\\ne0$ equivalent to invertibility?', 'Nonzero determinant implies full column independence; equivalently the associated endomorphism has zero kernel and hence is invertible.'), ('Compute the determinant of a diagonal matrix.', 'Only the identity permutation contributes, so the determinant is the product of diagonal entries.'), ('Prove $\\operatorname{tr}(PAP^{-1})=\\operatorname{tr}(A)$.', 'Use cyclicity: $\\operatorname{tr}(PAP^{-1})=\\operatorname{tr}(AP^{-1}P)=\\operatorname{tr}(A)$.'), ('What determinant does a reflection of $\\mathbb R^n$ across a hyperplane have?', 'It has eigenvalues $1$ on the hyperplane and $-1$ on a normal direction, so determinant $-1$.'), ('Compute the trace of a rank-one matrix $uv^T$.', 'The trace is $v^Tu=\\sum_i u_iv_i$.'), ('Show that determinant and trace are basis-independent for an endomorphism.', 'Two matrix representations are similar; determinant and trace are invariant under similarity.')]}, 'I/09': {'intro': 'Eigenvectors are directions preserved by an operator up to scaling, and eigenvalues are the corresponding scale factors. The characteristic polynomial packages all eigenvalues algebraically. This chapter emphasizes both geometric meaning and the limitations of eigenvector methods when a full eigenbasis does not exist.', 'sections': [('Eigenvectors and eigenvalues', 'A nonzero $v$ is an eigenvector of $T$ with eigenvalue $\\lambda$ when $T(v)=\\lambda v$.'), ('Eigenspaces', '$E_\\lambda=\\ker(T-\\lambda I)$ is a subspace. Distinct eigenspaces meet only at zero.'), ('Characteristic polynomial', 'For a matrix $A$, $\\chi_A(t)=\\det(tI-A)$. Its roots are precisely the eigenvalues over the chosen field.'), ('Algebraic and geometric multiplicity', 'The algebraic multiplicity is the multiplicity of a root of $\\chi_A$; the geometric multiplicity is $\\dim E_\\lambda$ and never exceeds it.'), ('Independence of eigenvectors', 'Eigenvectors associated with distinct eigenvalues are linearly independent.'), ('Field dependence', 'A real matrix may have no real eigenvalues but acquire complex eigenvalues after extending scalars to $\\mathbb C$.')], 'facts': [('Distinct eigenvalues give independence', 'Eigenvectors corresponding to distinct eigenvalues are linearly independent.', 'Use induction. Apply $T-\\lambda_r I$ to a dependence relation; the last term vanishes and the remaining coefficients are multiplied by nonzero scalars.'), ('Geometric multiplicity bound', 'For an eigenvalue $\\lambda$, $1\\le\\dim E_\\lambda\\le$ its algebraic multiplicity.', 'The lower bound is the definition of eigenvalue. The upper bound follows after choosing a basis beginning with an eigenspace basis, which forces a block with $\\lambda$ repeated on the diagonal.')], 'examples': [('Diagonal matrix', 'For $D=\\operatorname{diag}(d_1,\\ldots,d_n)$, each standard vector is an eigenvector with eigenvalue $d_i$.'), ('Rotation', 'A nontrivial planar rotation has no real eigenvectors unless the angle is $0$ or $\\pi$, but over $\\mathbb C$ it has eigenvalues $e^{\\pm i\\theta}$.'), ('Shear', '$\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}$ has only the eigenvalue $1$ and only a one-dimensional eigenspace.')], 'ex': [('Find the eigenvalues of $\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$.', 'They are the diagonal entries $2$ and $3$.'), ('Find the eigenspace for eigenvalue $1$ of $\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}$.', 'Solve $(A-I)v=0$, giving $y=0$; the eigenspace is the span of $(1,0)$.'), ('Why is the zero vector excluded from the definition of eigenvector?', 'It satisfies $T(0)=\\lambda0$ for every scalar, so including it would carry no information about the operator.'), ('Prove eigenspaces are subspaces.', 'They are kernels of the linear maps $T-\\lambda I$.'), ('Show that eigenvalues depend on the scalar field.', 'The real rotation by $90^\\circ$ has characteristic polynomial $t^2+1$, with no real roots but roots $\\pm i$ over $\\mathbb C$.'), ('If $T$ is invertible, can $0$ be an eigenvalue?', 'No. A zero eigenvalue would give a nonzero vector in the kernel.'), ('What are the eigenvalues of a triangular matrix?', 'They are its diagonal entries, because the characteristic polynomial is the product of $t-a_{ii}$.'), ('Explain the difference between algebraic and geometric multiplicity for a shear.', 'For the $2\\times2$ shear, eigenvalue $1$ has algebraic multiplicity $2$ but geometric multiplicity $1$.')]}, 'I/10': {'intro': 'Invariant subspaces let a large operator be studied through smaller pieces. Triangularization is the systematic expression of this idea: once an invariant flag is chosen, the matrix becomes triangular and its diagonal reveals the eigenvalues. Over an algebraically closed field, every operator on a nonzero finite-dimensional space admits such a form.', 'sections': [('Invariant subspaces', 'A subspace $U$ is $T$-invariant when $T(U)\\subseteq U$. The restriction $T|_U$ is then an operator on $U$.'), ('Quotient operators', 'If $U$ is invariant, $T$ induces an operator on $V/U$ by $v+U\\mapsto T(v)+U$.'), ('Invariant flags', 'A chain $0=V_0\\subset V_1\\subset\\cdots\\subset V_n=V$ with $\\dim V_k=k$ and each $V_k$ invariant is a complete invariant flag.'), ('Triangular matrices and flags', 'An operator is upper triangular in a basis exactly when the spans of its initial basis segments form an invariant flag.'), ('Triangularization theorem', 'Over an algebraically closed field, every operator on a finite-dimensional nonzero vector space is triangularizable.'), ('Block triangular form', 'Even without a complete flag, a single invariant subspace produces a block upper-triangular matrix, separating the restriction and quotient actions.')], 'facts': [('Flag criterion for triangularity', 'A basis $v_1,\\ldots,v_n$ gives an upper-triangular matrix for $T$ if and only if $\\operatorname{span}(v_1,\\ldots,v_k)$ is invariant for every $k$.', 'Upper triangularity says $T(v_k)$ lies in the span of the first $k$ basis vectors. This is exactly the invariant-flag condition.'), ('Triangularization over an algebraically closed field', 'Every operator on a finite-dimensional complex vector space has an upper-triangular matrix in some basis.', 'Choose an eigenvector, use its span as the first invariant subspace, pass to the quotient, and induct on dimension.')], 'examples': [('Nilpotent shift', 'The map $N(e_1)=0$, $N(e_k)=e_{k-1}$ preserves the standard flag and is strictly upper triangular in the reversed standard convention.'), ('Polynomial operator', 'Differentiation preserves the nested polynomial spaces $\\mathcal P_0\\subset\\mathcal P_1\\subset\\cdots$.'), ('Real rotation', 'A planar rotation through $90^\\circ$ has no invariant real line, so it cannot be triangularized over $\\mathbb R$.')], 'ex': [('Show every eigenspace is invariant.', 'If $v\\in E_\\lambda$, then $T(v)=\\lambda v\\in E_\\lambda$.'), ('If $U$ is invariant, prove the quotient operator is well-defined.', 'If $v+U=w+U$, then $v-w\\in U$, so $T(v-w)\\in U$ and $T(v)+U=T(w)+U$.'), ('Why does an upper-triangular matrix preserve the coordinate flag?', 'The first $k$ columns have zeros below row $k$, so vectors supported in the first $k$ coordinates map back into that subspace.'), ('Give an invariant subspace of a diagonal operator.', 'The span of any subset of eigenbasis vectors is invariant.'), ('Why may triangularization fail over $\\mathbb R$?', 'The induction starts by choosing an eigenvector; a real operator can have no real eigenvalue.'), ('Show the characteristic polynomial of a triangular matrix is the product of $t-a_{ii}$.', 'The matrix $tI-A$ is triangular, so its determinant is the product of its diagonal entries.'), ('Describe the block form associated with an invariant subspace $U$.', 'Choose a basis of $U$ and extend it to $V$. The lower-left block is zero because $T(U)\\subseteq U$.'), ('Explain why triangularization already reveals all eigenvalues.', 'The characteristic polynomial is the product of $t$ minus the diagonal entries, so the diagonal entries are precisely the eigenvalues with multiplicity.')]}, 'I/11': {'intro': 'Diagonalization asks whether an operator can be decomposed into independent one-dimensional modes. The minimal polynomial gives the sharp algebraic criterion: an operator is diagonalizable exactly when its minimal polynomial splits into distinct linear factors. This viewpoint unifies eigenvalue counting with polynomial identities satisfied by the operator.', 'sections': [('Diagonalizable operators', 'An operator is diagonalizable when it has a basis of eigenvectors, equivalently when some matrix representation is diagonal.'), ('Direct sums of eigenspaces', 'If the characteristic polynomial splits, diagonalizability is equivalent to $V$ being the direct sum of its eigenspaces.'), ('Minimal polynomial', 'The minimal polynomial $m_T$ is the monic polynomial of least positive degree with $m_T(T)=0$.'), ('Divisibility property', 'Every polynomial $p$ with $p(T)=0$ is divisible by $m_T$. In particular, $m_T$ divides the characteristic polynomial.'), ('Square-free criterion', 'If $m_T$ splits, then $T$ is diagonalizable exactly when $m_T$ has no repeated root.'), ('Spectral projectors by interpolation', 'For distinct eigenvalues, Lagrange interpolation polynomials in $T$ produce projections onto eigenspaces.')], 'facts': [('Dimension criterion', 'If $\\chi_T$ splits, then $T$ is diagonalizable if and only if the sum of eigenspace dimensions equals $\\dim V$.', 'Distinct eigenspaces form a direct sum. Their union of bases is an eigenbasis exactly when the direct sum has full dimension.'), ('Minimal-polynomial criterion', 'An operator is diagonalizable if and only if its minimal polynomial is a product of distinct linear factors.', 'For a diagonal operator, a polynomial annihilates it exactly when it vanishes at every diagonal eigenvalue. Conversely, use Lagrange polynomials to construct complementary eigenspace projectors.')], 'examples': [('Projection', 'A projection $P^2=P$ has minimal polynomial dividing $t(t-1)$, which has distinct roots, so every projection is diagonalizable.'), ('Involution', 'If $T^2=I$ over characteristic not $2$, then $m_T$ divides $(t-1)(t+1)$, so $T$ is diagonalizable.'), ('Nontrivial shear', 'The shear has minimal polynomial $(t-1)^2$, so it is not diagonalizable.')], 'ex': [('Why is every operator with distinct eigenvalues equal in number to the dimension diagonalizable?', 'Eigenvectors for distinct eigenvalues are independent, yielding a basis.'), ('Find the minimal polynomial of a diagonal matrix with diagonal entries $1,1,3$.', 'It is $(t-1)(t-3)$; repeated diagonal occurrences do not create repeated factors in the minimal polynomial.'), ('Find the minimal polynomial of a nontrivial $2\\times2$ shear.', 'It is $(t-1)^2$: $A-I$ is nonzero but $(A-I)^2=0$.'), ('Show every projection is diagonalizable without computing a determinant.', 'Decompose $V=\\operatorname{im}P\\oplus\\ker P$. The operator acts as $1$ on the image and $0$ on the kernel.'), ('If $T^2=I$, what are the possible eigenvalues?', 'Any eigenvalue $\\lambda$ satisfies $\\lambda^2=1$, so $\\lambda=\\pm1$.'), ('Why must $m_T$ divide every annihilating polynomial?', 'Divide $p$ by $m_T$; the remainder has smaller degree and also annihilates $T$, so minimality forces the remainder to vanish.'), ('Construct the spectral projector onto $E_{\\lambda_i}$ for distinct eigenvalues.', 'Use $P_i=\\prod_{j\\ne i}(T-\\lambda_jI)/(\\lambda_i-\\lambda_j)$; it equals $1$ on $E_{\\lambda_i}$ and $0$ on the other eigenspaces.'), ('Explain why repeated roots in the characteristic polynomial do not by themselves prevent diagonalization.', 'The identity matrix has characteristic polynomial $(t-1)^n$ but is diagonal; what matters is the minimal polynomial, which is $t-1$.')]}, 'I/12': {'intro': 'When diagonalization fails, canonical forms measure the failure rather than hiding it. Jordan form over an algebraically closed field records nilpotent chains attached to each eigenvalue, while rational canonical form works over arbitrary fields using invariant factors. Both arise from viewing a vector space as a module over the polynomial ring via $p\\cdot v=p(T)v$.', 'sections': [('Generalized eigenvectors', 'A vector lies in the generalized eigenspace for $\\lambda$ if $(T-\\lambda I)^k v=0$ for some $k$.'), ('Nilpotent operators', 'Nilpotent operators organize into chains $v,Nv,\\ldots$. Their Jordan blocks encode chain lengths.'), ('Jordan blocks', 'A Jordan block $J_r(\\lambda)$ has $\\lambda$ on the diagonal and ones on the superdiagonal. Its minimal polynomial is $(t-\\lambda)^r$.'), ('Jordan canonical form', 'Over an algebraically closed field, every operator is similar to a direct sum of Jordan blocks, unique up to block order.'), ('Primary decomposition', 'If the minimal polynomial factors into pairwise coprime powers, the space decomposes into invariant primary components.'), ('Rational canonical form', 'Over any field, invariant factors determine a block diagonal companion-matrix form. Jordan form is the split refinement of this module-theoretic structure.')], 'facts': [('Generalized eigenspace decomposition', 'If $m_T(t)=\\prod_i(t-\\lambda_i)^{r_i}$ with distinct $\\lambda_i$, then $V=\\bigoplus_i\\ker(T-\\lambda_iI)^{r_i}$.', 'The factors are pairwise coprime. Bézout identities in $\\mathbb F[t]$ produce polynomial projectors whose images are the primary components.'), ('Jordan block invariants', 'For a nilpotent operator, the numbers $\\dim\\ker N^k$ determine the Jordan block sizes.', 'The increment $\\dim\\ker N^k-\\dim\\ker N^{k-1}$ counts blocks of size at least $k$; successive differences recover the exact sizes.')], 'examples': [('Single Jordan block', '$J_3(0)$ is nilpotent of index $3$; kernel dimensions are $1,2,3$.'), ('Two blocks', '$J_2(0)\\oplus J_1(0)$ has kernel dimensions $2,3$, revealing two blocks, one of which has length at least $2$.'), ('Companion matrix', 'The companion matrix of a monic polynomial has that polynomial as both characteristic and minimal polynomial when it represents a cyclic module.')], 'ex': [('Compute the minimal polynomial of $J_4(\\lambda)$.', 'It is $(t-\\lambda)^4$ because the nilpotent part has index $4$.'), ('What is the geometric multiplicity of an eigenvalue in Jordan form?', 'It equals the number of Jordan blocks carrying that eigenvalue.'), ('How can kernel dimensions reveal nilpotent block sizes?', 'The increment from $\\ker N^{k-1}$ to $\\ker N^k$ counts blocks of size at least $k$.'), ('When is a Jordan matrix diagonal?', 'Exactly when every Jordan block has size $1$.'), ('Why is Jordan form not always available over $\\mathbb R$?', 'The characteristic/minimal polynomial may not split into linear factors over $\\mathbb R$.'), ('State the advantage of rational canonical form.', 'It exists over every field and does not require the characteristic polynomial to split.'), ('Show that generalized eigenspaces are invariant.', 'If $(T-\\lambda I)^k v=0$, then $(T-\\lambda I)^kT(v)=T(T-\\lambda I)^kv=0$.'), ('Relate the largest Jordan block for $\\lambda$ to the minimal polynomial.', 'Its size is the exponent of $(t-\\lambda)$ in the minimal polynomial.')]}, 'I/13': {'intro': 'Inner products add geometry to linear algebra. Length, angle, orthogonality and best approximation all come from a positive definite sesquilinear form. The complex case forces careful placement of conjugation, but the resulting theory unifies Euclidean geometry with finite-dimensional Hilbert-space methods.', 'sections': [('Inner products', 'A real inner product is symmetric bilinear and positive definite; a complex inner product is conjugate symmetric and sesquilinear.'), ('Norm and distance', 'The norm is $\\|v\\|=\\sqrt{\\langle v,v\\rangle}$ and the induced distance is $\\|v-w\\|$.'), ('Cauchy–Schwarz', '$|\\langle u,v\\rangle|\\le\\|u\\|\\|v\\|$, with equality precisely when the vectors are linearly dependent.'), ('Orthogonality', 'Vectors are orthogonal when their inner product is zero. Orthogonal nonzero lists are automatically independent.'), ('Orthogonal complements', 'For a subspace $U$, $U^\\perp=\\{v:\\langle v,u\\rangle=0\\ \\forall u\\in U\\}$. In finite dimensions, $V=U\\oplus U^\\perp$.'), ('Parallelogram and polarization', 'The inner product determines the norm, and conversely a norm comes from an inner product exactly when it satisfies the parallelogram law.')], 'facts': [('Cauchy–Schwarz inequality', 'For all $u,v$ in an inner-product space, $|\\langle u,v\\rangle|\\le\\|u\\|\\|v\\|$.', 'If $v\\ne0$, apply positivity to $u-(\\langle u,v\\rangle/\\|v\\|^2)v$ and expand. The case $v=0$ is immediate.'), ('Pythagorean theorem', 'If $u\\perp v$, then $\\|u+v\\|^2=\\|u\\|^2+\\|v\\|^2$.', 'Expand $\\langle u+v,u+v\\rangle$ and use conjugate symmetry together with the vanishing cross terms.')], 'examples': [('Euclidean product', 'On $\\mathbb R^n$, $\\langle x,y\\rangle=x^Ty$.'), ('Weighted product', 'For positive weights $w_i$, $\\langle x,y\\rangle=\\sum_i w_ix_iy_i$ is an inner product.'), ('Function product', 'On continuous functions, $\\langle f,g\\rangle=\\int_0^1 f(t)\\overline{g(t)}\\,dt$ is an inner product.')], 'ex': [('Show nonzero orthogonal vectors are independent.', 'Take a dependence relation and inner-product with one vector; all cross terms vanish, leaving its coefficient times a positive norm squared.'), ('Compute the angle between $(1,0)$ and $(1,1)$ in $\\mathbb R^2$.', 'The cosine is $1/(1\\cdot\\sqrt2)=1/\\sqrt2$, so the angle is $\\pi/4$.'), ('Find the orthogonal complement of the $x$-axis in $\\mathbb R^2$.', 'It is the $y$-axis.'), ('Verify the parallelogram identity.', 'Expand $\\|u+v\\|^2+\\|u-v\\|^2$; the cross terms cancel, leaving $2\\|u\\|^2+2\\|v\\|^2$.'), ('Why is complex conjugation necessary in the standard complex inner product?', 'Without conjugation, $\\langle v,v\\rangle$ need not be real or positive; conjugation gives $\\sum|v_i|^2$.'), ('Show $U\\cap U^\\perp=\\{0\\}$.', 'If $v$ lies in both, then $\\langle v,v\\rangle=0$, hence $v=0$ by positive definiteness.'), ('Prove the triangle inequality from Cauchy–Schwarz.', 'Expand $\\|u+v\\|^2$ and bound the real part of $\\langle u,v\\rangle$ by $\\|u\\|\\|v\\|$.'), ('Give an example of two different inner products on $\\mathbb R^2$.', 'The standard product and $\\langle x,y\\rangle=2x_1y_1+x_2y_2$ are distinct inner products.')]}, 'I/14': {'intro': 'Gram–Schmidt converts an arbitrary independent list into an orthonormal list spanning the same nested subspaces. Orthogonal projection then gives canonical decompositions and solves least-squares problems. This chapter connects exact geometry with the numerical algorithms QR factorization and normal equations.', 'sections': [('Orthonormal lists', 'A list is orthonormal when its vectors have norm one and are pairwise orthogonal. Coordinates in an orthonormal basis are inner products.'), ('Gram–Schmidt process', 'Successively subtract from each vector its projections onto the previously constructed orthonormal vectors, then normalize.'), ('Projection onto a subspace', 'For an orthonormal basis $e_1,\\ldots,e_r$ of $U$, $P_Uv=\\sum_i\\langle v,e_i\\rangle e_i$.'), ('Best approximation', '$P_Uv$ is the unique vector in $U$ minimizing $\\|v-u\\|$.'), ('QR factorization', 'Applying Gram–Schmidt to independent columns of $A$ produces $A=QR$, with $Q$ having orthonormal columns and $R$ upper triangular.'), ('Least squares', 'For full-column-rank $A$, the least-squares solution satisfies $A^*Ax=A^*b$ and can be computed more stably using QR.')], 'facts': [('Gram–Schmidt theorem', 'Every finite independent list in an inner-product space can be replaced by an orthonormal list with the same successive spans.', 'At step $k$, subtract the projection of $v_k$ onto the span already constructed. Independence guarantees the remainder is nonzero; normalization finishes the step.'), ('Projection theorem', 'For finite-dimensional $U$, every $v$ decomposes uniquely as $v=P_Uv+(v-P_Uv)$ with the first term in $U$ and the second in $U^\\perp$.', 'Use an orthonormal basis of $U$ to define $P_Uv$. Direct calculation shows the residual is orthogonal to every basis vector and hence to $U$.')], 'examples': [('Two planar vectors', 'Starting from $(1,0)$ and $(1,1)$, Gram–Schmidt returns $(1,0)$ and $(0,1)$.'), ('Projection onto a line', 'Projection onto the line spanned by unit $u$ is $P(v)=\\langle v,u\\rangle u$.'), ('Least squares line fitting', 'The columns $1$ and $t$ form a design matrix; projection of data onto their column space gives the best affine fit.')], 'ex': [('Apply Gram–Schmidt to $(1,1)$ and $(1,-1)$.', 'They are already orthogonal; normalize each by $\\sqrt2$.'), ('Project $(2,3)$ onto the $x$-axis.', 'The projection is $(2,0)$.'), ('Why is the projection residual orthogonal to the subspace?', 'Subtracting all orthonormal-basis components makes its inner product with each basis vector zero.'), ('Prove the best-approximation property.', 'For $u\\in U$, write $v-u=(v-P_Uv)+(P_Uv-u)$; the two terms are orthogonal, so Pythagoras is minimized exactly when $u=P_Uv$.'), ('What are the dimensions of $Q$ and $R$ for an $m\\times n$ matrix of full column rank?', 'In reduced QR, $Q$ is $m\\times n$ with orthonormal columns and $R$ is invertible $n\\times n$ upper triangular.'), ('Why can normal equations be less stable than QR?', 'Forming $A^*A$ squares the condition number, amplifying numerical sensitivity.'), ('Show an orthogonal projection satisfies $P^2=P$.', 'Once a vector lies in $U$, projecting again leaves it unchanged; hence $P(Pv)=Pv$.'), ('Show $I-P_U$ projects onto $U^\\perp$.', 'The decomposition theorem gives $v-P_Uv\\in U^\\perp$, and vectors already in $U^\\perp$ are fixed by $I-P_U$.')]}, 'I/15': {'intro': 'Orthogonal and unitary operators are the linear symmetries of inner-product geometry. They preserve lengths, angles and orthogonality, and their matrices satisfy $Q^*Q=I$. Reflections, rotations and Householder transformations show how geometric symmetries become structured matrices.', 'sections': [('Isometries', 'A linear map is an isometry when it preserves norms, equivalently inner products.'), ('Orthogonal and unitary matrices', 'A real matrix is orthogonal when $Q^TQ=I$; a complex matrix is unitary when $Q^*Q=I$.'), ('Equivalent characterizations', 'For a square matrix, orthonormal columns, orthonormal rows and inverse equal to adjoint are equivalent.'), ('Determinant and orientation', 'A real orthogonal matrix has determinant $\\pm1$. Determinant $+1$ gives orientation-preserving transformations.'), ('Reflections and Householder maps', 'For unit $u$, $H=I-2uu^*$ reflects across the hyperplane $u^\\perp$.'), ('Rotations and planar blocks', 'Real orthogonal operators decompose into invariant one- and two-dimensional pieces, with planar rotation blocks on the latter.')], 'facts': [('Inner-product preservation criterion', 'A linear map preserves inner products if and only if it preserves norms.', 'One direction is immediate. For the converse, recover the inner product from the norm using the polarization identity.'), ('Adjoint inverse criterion', 'A matrix $Q$ is unitary exactly when $Q^{-1}=Q^*$.', 'This is simply a rearrangement of $Q^*Q=I$, with invertibility automatic.')], 'examples': [('Planar rotation', 'The standard rotation matrix is orthogonal with determinant $1$.'), ('Reflection', '$\\operatorname{diag}(1,-1)$ reflects across the $x$-axis and has determinant $-1$.'), ('Permutation matrix', 'Every permutation matrix is orthogonal because its columns are a rearrangement of the standard orthonormal basis.')], 'ex': [('Show an orthogonal matrix preserves Euclidean norm.', '$\\|Qx\\|^2=x^TQ^TQx=x^Tx$.'), ('Why do orthogonal matrices have determinant $\\pm1$?', 'Taking determinants in $Q^TQ=I$ gives $(\\det Q)^2=1$.'), ('Verify a Householder matrix is orthogonal.', 'With $P=uu^T$ and $P^2=P$, $(I-2P)^2=I$. Since it is symmetric, its transpose is its inverse.'), ('What does a unitary operator do to an orthonormal basis?', 'It sends it to another orthonormal basis because all pairwise inner products are preserved.'), ('Show the inverse of a unitary matrix is unitary.', 'If $Q^{-1}=Q^*$, then $(Q^{-1})^*=Q$ and $(Q^{-1})^*Q^{-1}=QQ^*=I$.'), ('Give an orthogonal matrix with determinant $-1$ in $\\mathbb R^3$.', 'For example $\\operatorname{diag}(1,1,-1)$.'), ('Why is every eigenvalue of a complex unitary matrix of modulus one?', 'If $Qv=\\lambda v$, norm preservation gives $\\|v\\|=\\|Qv\\|=|\\lambda|\\|v\\|$, so $|\\lambda|=1$.'), ('Explain why orthogonal change of coordinates is numerically attractive.', 'Its inverse is the transpose and its condition number in the Euclidean norm is $1$, so it does not amplify relative errors.')]}, 'I/16': {'intro': 'The spectral theorem is the central structure theorem for self-adjoint, symmetric and normal operators. It says that the right compatibility with the inner product upgrades triangularization to orthonormal diagonalization. Functional calculus and positive operators then become simple operations on eigenvalues.', 'sections': [('Adjoints', 'The adjoint $T^*$ is characterized by $\\langle Tv,w\\rangle=\\langle v,T^*w\\rangle$.'), ('Self-adjoint and normal operators', '$T$ is self-adjoint when $T=T^*$ and normal when $TT^*=T^*T$.'), ('Reality of the spectrum', 'Eigenvalues of self-adjoint operators are real, and eigenspaces for distinct eigenvalues are orthogonal.'), ('Spectral theorem', 'A finite-dimensional complex operator is normal if and only if it is unitarily diagonalizable. Over $\\mathbb R$, symmetric operators are orthogonally diagonalizable.'), ('Functional calculus', 'If $T=UDU^*$, define $f(T)=Uf(D)U^*$ for functions defined on the spectrum.'), ('Positive operators', 'A self-adjoint operator is positive semidefinite when $\\langle Tv,v\\rangle\\ge0$; spectrally this means all eigenvalues are nonnegative.')], 'facts': [('Orthogonality of self-adjoint eigenspaces', 'Eigenvectors of a self-adjoint operator associated with distinct eigenvalues are orthogonal.', 'If $Tv=\\lambda v$ and $Tw=\\mu w$, then $\\lambda\\langle v,w\\rangle=\\langle Tv,w\\rangle=\\langle v,Tw\\rangle=\\mu\\langle v,w\\rangle$.'), ('Finite-dimensional spectral theorem', 'Every self-adjoint operator on a finite-dimensional inner-product space has an orthonormal basis of eigenvectors.', 'Choose an eigenvector, take its orthogonal complement, show that complement is invariant under self-adjointness, and induct on dimension.')], 'examples': [('Real symmetric matrix', '$\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}$ has orthogonal eigenvectors $(1,1)$ and $(1,-1)$ with eigenvalues $3$ and $1$.'), ('Positive square root', 'For positive $A=UDU^*$, set $A^{1/2}=UD^{1/2}U^*$; then $A^{1/2}$ is positive and squares to $A$.'), ('Normal but not self-adjoint', 'A nontrivial complex unitary rotation is normal but may not be self-adjoint.')], 'ex': [('Show eigenvalues of a self-adjoint operator are real.', 'If $Tv=\\lambda v$, then $\\lambda\\|v\\|^2=\\langle Tv,v\\rangle=\\langle v,Tv\\rangle=\\overline\\lambda\\|v\\|^2$.'), ('Diagonalize $\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}$ orthogonally.', 'Normalize eigenvectors $(1,1)$ and $(1,-1)$ to form $Q$; then $Q^TAQ=\\operatorname{diag}(3,1)$.'), ('Why is every unitary operator normal?', '$UU^*=U^*U=I$.'), ('Show a positive semidefinite operator has nonnegative eigenvalues.', 'For an eigenvector $v$, $\\langle Tv,v\\rangle=\\lambda\\|v\\|^2\\ge0$.'), ('Define $T^2$ using spectral functional calculus.', 'If $T=UDU^*$ then $T^2=UD^2U^*$, corresponding to $f(t)=t^2$.'), ('Why is the orthogonal complement of an invariant eigenspace also invariant for a self-adjoint operator?', 'If $w$ is orthogonal to the eigenspace and $v$ is in it, then $\\langle Tw,v\\rangle=\\langle w,Tv\\rangle=\\lambda\\langle w,v\\rangle=0$.'), ('What extra conclusion does normality give beyond triangularization?', 'A normal operator can be diagonalized by a unitary basis change, so the basis can be chosen orthonormal.'), ('Relate spectral theorem to quadratic forms.', 'A real symmetric matrix can be orthogonally diagonalized, reducing its quadratic form to a sum of scalar multiples of squares.')]}, 'I/17': {'intro': "Quadratic forms encode second-order geometry. Symmetric bilinear forms and symmetric matrices represent the same finite-dimensional data once a basis is chosen. Congruence, not similarity, is the natural basis-change relation, and Sylvester's law of inertia identifies the basis-independent signature.", 'sections': [('Quadratic and bilinear forms', 'A quadratic form on a real vector space has the form $q(v)=B(v,v)$ for a symmetric bilinear form $B$.'), ('Matrix representation', 'In coordinates, $q(x)=x^TAx$ with $A$ symmetric. Cross terms appear twice the corresponding off-diagonal entry.'), ('Polarization', 'Over characteristic not $2$, the symmetric bilinear form is recovered from $q$ by $B(u,v)=\\tfrac12(q(u+v)-q(u)-q(v))$.'), ('Congruence', 'Under coordinate change $x=Py$, the matrix transforms as $A\\mapsto P^TAP$.'), ('Sylvester law of inertia', 'Every real symmetric quadratic form is congruent to a diagonal form with entries $1,-1,0$, and the counts of positive, negative and zero entries are invariant.'), ('Definiteness', 'A symmetric form is positive definite exactly when all eigenvalues are positive; equivalent criteria include positivity of leading principal minors.')], 'facts': [('Polarization identity', 'For a real quadratic form $q(v)=B(v,v)$ with symmetric bilinear $B$, $B(u,v)=\\frac12(q(u+v)-q(u)-q(v))$.', 'Expand $q(u+v)=B(u,u)+2B(u,v)+B(v,v)$ and rearrange.'), ('Sylvester law of inertia', 'The numbers of positive, negative and zero squares in a real diagonalization by congruence are basis-independent.', 'A congruence change is an invertible change of variables; maximal dimensions of subspaces on which the form is positive or negative definite are intrinsic and determine the counts.')], 'examples': [('Conic form', '$x^2+2xy+y^2=(x+y)^2$ has rank one and is positive semidefinite.'), ('Indefinite form', '$x^2-y^2$ has inertia $(1,1,0)$ and vanishes on the two lines $x=\\pm y$.'), ('Hessian viewpoint', 'At a critical point of a smooth function, the Hessian defines a quadratic form whose signature describes local second-order behavior.')], 'ex': [('Find the symmetric matrix for $q(x,y)=2x^2+6xy+5y^2$.', '$A=\\begin{pmatrix}2&3\\\\3&5\\end{pmatrix}$ because the cross term is $2a_{12}xy$.'), ('Recover the bilinear form from a quadratic form by polarization.', 'Use $B(u,v)=\\tfrac12(q(u+v)-q(u)-q(v))$.'), ('Why does a basis change act by congruence rather than similarity?', 'Both copies of the coordinate vector change in $x^TAx$, producing $y^TP^TAPy$.'), ('Determine the definiteness of $x^2-y^2$.', 'It is indefinite because it takes both positive and negative values.'), ('What is the inertia of $x^2+y^2$?', '$(2,0,0)$: two positive directions, no negative or null directions.'), ('Show positive definite implies nonsingular.', 'A nonzero kernel vector would satisfy $q(v)=v^TAv=0$, contradicting positive definiteness.'), ('Diagonalize $2xy$ by a linear change of variables.', 'Set $u=(x+y)/\\sqrt2$, $v=(x-y)/\\sqrt2$; then $2xy=u^2-v^2$.'), ('Explain the role of the spectral theorem for symmetric quadratic forms.', 'Orthogonal diagonalization of the symmetric matrix expresses the form as a weighted sum of coordinate squares.')]}, 'I/18': {'intro': 'The singular-value decomposition is the universal orthogonal factorization of a linear map between finite-dimensional inner-product spaces. Unlike eigenvalue decomposition, it applies to every rectangular matrix. Singular values quantify stretching, rank, conditioning and optimal low-rank approximation.', 'sections': [('Singular values', 'The singular values of $A$ are the nonnegative square roots of the eigenvalues of $A^*A$.'), ('SVD theorem', 'Every $m\\times n$ matrix has a factorization $A=U\\Sigma V^*$ with $U,V$ unitary (orthogonal over $\\mathbb R$) and $\\Sigma$ diagonal rectangular with nonnegative entries.'), ('Construction from the spectral theorem', 'Diagonalize $A^*A$ to obtain right singular vectors; normalize their images under $A$ to obtain left singular vectors.'), ('Rank and norms', 'The rank is the number of positive singular values. The operator norm is the largest singular value, and the Frobenius norm squared is the sum of squared singular values.'), ('Pseudoinverse', 'Replacing each nonzero singular value by its reciprocal gives the Moore–Penrose pseudoinverse.'), ('Low-rank approximation', 'Truncating the SVD after the largest $r$ singular values gives a best rank-$r$ approximation in operator and Frobenius norms.')], 'facts': [('Singular-value decomposition', 'For every matrix $A\\in\\mathbb F^{m\\times n}$, there exist unitary $U,V$ and a rectangular diagonal $\\Sigma$ with nonnegative entries such that $A=U\\Sigma V^*$.', 'Apply the spectral theorem to the positive semidefinite matrix $A^*A$. For each positive eigenvalue $\\sigma_i^2$, set $u_i=Av_i/\\sigma_i$; extend the resulting orthonormal lists to bases.'), ('Rank from singular values', 'The number of nonzero singular values equals $\\operatorname{rank}A$.', 'The kernels of $A$ and $A^*A$ coincide, so they have the same nullity. Rank–nullity then shows $A^*A$ has as many positive eigenvalues as the rank of $A$.')], 'examples': [('Diagonal matrix', 'For a real diagonal matrix, singular values are the absolute values of its diagonal entries.'), ('Rank-one matrix', 'If $A=uv^*$, there is a single nonzero singular value $\\|u\\|\\|v\\|$.'), ('Condition number', 'For invertible $A$, the Euclidean condition number is $\\kappa_2(A)=\\sigma_{\\max}/\\sigma_{\\min}$.')], 'ex': [('Find the singular values of $\\operatorname{diag}(3,-2)$.', 'They are $3$ and $2$, the square roots of eigenvalues $9$ and $4$ of $A^TA$.'), ('Why is $A^*A$ positive semidefinite?', '$\\langle A^*Av,v\\rangle=\\langle Av,Av\\rangle=\\|Av\\|^2\\ge0$.'), ('Show $\\ker(A^*A)=\\ker A$.', 'If $Av=0$ then clearly $A^*Av=0$. Conversely, $A^*Av=0$ implies $0=\\langle A^*Av,v\\rangle=\\|Av\\|^2$.'), ('What is the rank of a matrix with singular values $5,2,0,0$?', 'The rank is $2$, the number of nonzero singular values.'), ('Describe the pseudoinverse of a diagonal singular-value matrix.', 'Transpose the rectangular shape and replace each positive $\\sigma_i$ by $1/\\sigma_i$, leaving zeros unchanged.'), ('Why is SVD available for rectangular matrices while diagonalization is not?', 'SVD uses the square self-adjoint matrices $A^*A$ and $AA^*$ and two possibly different orthonormal bases; ordinary diagonalization requires an endomorphism.'), ('What does the largest singular value measure?', 'It is $\\max_{\\|x\\|=1}\\|Ax\\|$, the maximum stretching factor.'), ('Explain truncated SVD conceptually.', 'Keep only the dominant orthogonal input/output modes and their singular values; the discarded modes contribute the smallest possible approximation error for the prescribed rank.')]}}

STATUS_FIELDS=["volume","chapter_code","chapter_title","status","legacy_source_status","mapped_rule_count","canonical_path","next_action"]

def tex_escape_title(s):
    return s

def chapter_num(code):
    return int(code.split("/")[1])

def make_chapter(code,title,slug):
    d=DATA[code]
    n=chapter_num(code)
    prefix=f"i{n:02d}"
    out=[
      f"\\\\chapter{{{title}}}",
      f"\\\\label{{ch:{prefix}-{slug.replace('ch'+str(n).zfill(2)+'_','').replace('_','-')}}}",
      "",
      d["intro"],
      "",
      "\\\\section*{Learning goals}",
      "By the end of the chapter, the reader should be able to:",
      "\\\\begin{itemize}"
    ]
    for sec_title,_ in d["sections"]:
        out.append(f"\\\\item explain and use {sec_title.lower()} in basis-free and coordinate form;")
    out += ["\\\\end{itemize}",""]

    out += [
      "\\\\section*{Conceptual roadmap}",
      "The chapter is organized around a repeated pattern:",
      "\\[",
      "\\\\boxed{\\\\text{definition}\\\\;\\\\longrightarrow\\\\;\\\\text{structural theorem}"
      "\\\\;\\\\longrightarrow\\\\;\\\\text{coordinate calculation}\\\\;\\\\longrightarrow\\\\;\\\\text{application}.}",
      "\\]",
      "Whenever possible, we separate the invariant mathematical object from a chosen coordinate representation.",
      ""
    ]

    for sec_title,body in d["sections"]:
        out += [f"\\\\section{{{sec_title}}}", body, ""]

    out += ["\\\\section{Core structural results}",""]
    for j,(name,statement,proof) in enumerate(d["facts"],1):
        out += [
          f"\\\\begin{{theorem}}[{name}]\\\\label{{thm:{prefix}-{j:02d}}}",
          statement,
          "\\\\begin{proof}",
          proof,
          "\\\\end{proof}",
          "\\\\end{theorem}",
          ""
        ]

    out += ["\\\\section{Worked examples}",""]
    for j,(name,body) in enumerate(d["examples"],1):
        out += [
          f"\\\\begin{{example}}[{name}]\\\\label{{ex:{prefix}-worked-{j:02d}}}",
          body,
          "\\\\end{example}",
          ""
        ]

    out += [
      "\\\\section{Diagnostic checklist}",
      "Before moving on, it is useful to distinguish four levels of understanding:",
      "\\\\begin{enumerate}",
      "\\\\item recognize the definitions in unfamiliar examples;",
      "\\\\item prove the core structural statements without coordinates when possible;",
      "\\\\item translate the same statement into a matrix or coordinate computation;",
      "\\\\item know which hypotheses are essential and produce a counterexample when one is removed.",
      "\\\\end{enumerate}",
      "",
      "\\\\section{Exercises with complete solutions}",
      ""
    ]
    for j,(q,a) in enumerate(d["ex"],1):
        out += [
          f"\\\\begin{{exercise}}\\\\label{{exr:{prefix}-{j:02d}}}",
          q,
          "\\\\end{exercise}",
          "\\\\begin{hint}",
          "Identify the definition or structural theorem in this chapter that directly controls the question, then reduce the calculation to that statement.",
          "\\\\end{hint}",
          "\\\\begin{solution}",
          a,
          "\\\\end{solution}",
          ""
        ]

    out += [
      "\\\\section*{Chapter summary}",
      d["intro"],
      "The important habit is to move fluently between invariant statements and concrete coordinates while remembering which conclusions depend on finite dimensionality, the scalar field, or the inner product.",
      ""
    ]
    return "\n".join(out).rstrip()+"\n"

def read_status(path):
    with path.open("r",encoding="utf-8-sig",newline="") as f:
        return list(csv.DictReader(f,delimiter="\t"))

def write_status(path,rows):
    lines=["\t".join(STATUS_FIELDS)]
    for r in rows:
        lines.append("\t".join(str(r.get(k,"")) for k in STATUS_FIELDS))
    path.write_text("\n".join(lines)+"\n",encoding="utf-8")

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--repo",required=True)
    ap.add_argument("--start",type=int,required=True)
    ap.add_argument("--end",type=int,required=True)
    args=ap.parse_args()
    repo=Path(args.repo).resolve()
    vol=repo/"books/vol01_linear_algebra"
    status_path=repo/"editorial/CHAPTER_STATUS.tsv"
    rows=read_status(status_path)
    wanted={f"I/{n:02d}" for n in range(args.start,args.end+1)}
    mapping={code:(title,slug) for code,title,slug in CHAPTERS}
    changed=0
    for code in sorted(wanted):
        title,slug=mapping[code]
        chapter=vol/"chapters"/slug/"chapter.tex"
        chapter.parent.mkdir(parents=True,exist_ok=True)
        chapter.write_text(make_chapter(code,title,slug),encoding="utf-8")
        changed+=1
    for r in rows:
        if r.get("chapter_code") in wanted:
            title,slug=mapping[r["chapter_code"]]
            r["status"]="DRAFTED"
            r["canonical_path"]=f"books/vol01_linear_algebra/chapters/{slug}/chapter.tex"
            r["next_action"]="REVIEW_AND_INTEGRATE"
    write_status(status_path,rows)
    print(f"Reconstructed Volume I chapters {args.start:02d}-{args.end:02d}: {changed}")
    return 0

if __name__=="__main__":
    raise SystemExit(main())
